CREATE SCHEMA IF NOT EXISTS communication;
CREATE TABLE IF NOT EXISTS communication.chat_conversation("Id" uuid PRIMARY KEY,"TenantId" uuid NOT NULL,"Title" varchar(250) NOT NULL,"ConversationType" varchar(50) NOT NULL,"CreatedByUserId" uuid NOT NULL,"RelatedEntityId" uuid NULL,"RelatedEntityType" varchar(100) NULL,"IsClosed" boolean NOT NULL DEFAULT false,"ClosedAt" timestamptz NULL,"IsActive" boolean NOT NULL DEFAULT true,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"RowVersion" bytea NOT NULL DEFAULT '\\x');
CREATE TABLE IF NOT EXISTS communication.chat_participant("Id" uuid PRIMARY KEY,"TenantId" uuid NOT NULL,"ConversationId" uuid NOT NULL,"UserId" uuid NOT NULL,"Role" varchar(50) NOT NULL,"JoinedAt" timestamptz NOT NULL,"LastReadAt" timestamptz NULL,"IsMuted" boolean NOT NULL DEFAULT false,"IsActive" boolean NOT NULL DEFAULT true,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"RowVersion" bytea NOT NULL DEFAULT '\\x',CONSTRAINT uq_chat_participant UNIQUE("TenantId","ConversationId","UserId"));
CREATE TABLE IF NOT EXISTS communication.chat_message("Id" uuid PRIMARY KEY,"TenantId" uuid NOT NULL,"ConversationId" uuid NOT NULL,"SenderUserId" uuid NOT NULL,"MessageType" varchar(30) NOT NULL DEFAULT 'Text',"Message" varchar(5000) NOT NULL,"ReplyToMessageId" uuid NULL,"SentAt" timestamptz NOT NULL,"EditedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false,"IsActive" boolean NOT NULL DEFAULT true,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"RowVersion" bytea NOT NULL DEFAULT '\\x');
CREATE INDEX IF NOT EXISTS ix_chat_message_conversation ON communication.chat_message("TenantId","ConversationId","SentAt");
